CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE characters (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), system TEXT NOT NULL, schema_version INTEGER NOT NULL, revision INTEGER NOT NULL CHECK(revision >= 1), document_json TEXT NOT NULL CHECK(json_valid(document_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX characters_owner ON characters(owner_id);
CREATE TABLE character_permissions (character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')), PRIMARY KEY(character_id,user_id));
CREATE INDEX permissions_user ON character_permissions(user_id,character_id);
CREATE TABLE character_operations (operation_id TEXT PRIMARY KEY, character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE, revision INTEGER NOT NULL, base_revision INTEGER NOT NULL, client_id TEXT NOT NULL, actor_user_id TEXT NOT NULL REFERENCES users(id), origin TEXT NOT NULL, operations_json TEXT NOT NULL CHECK(json_valid(operations_json)), touched_paths_json TEXT NOT NULL CHECK(json_valid(touched_paths_json)), result_json TEXT NOT NULL CHECK(json_valid(result_json)), created_at TEXT NOT NULL, UNIQUE(character_id,revision));
CREATE TABLE operation_receipts (operation_id TEXT PRIMARY KEY, character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id), request_hash TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), created_at TEXT NOT NULL);
CREATE INDEX receipts_character ON operation_receipts(character_id);
CREATE TABLE external_bindings (id TEXT PRIMARY KEY, character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE, provider TEXT NOT NULL, external_id TEXT NOT NULL, mapping_version INTEGER NOT NULL, last_revision INTEGER NOT NULL DEFAULT 0, last_event_id TEXT NOT NULL DEFAULT '', origin TEXT NOT NULL, config_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(config_json)), UNIQUE(provider,external_id));
CREATE INDEX bindings_character ON external_bindings(character_id);
